/**
 * Combines all audit pages, finds requester_id, then
 * returns the newest public comment written by that requester.
 *
 * Works with these node names:
 *   • "Ticket Audit"            → first page
 *   • "Get Next Audit Page"     → page 2 … page N
 * If your node names differ, just change the strings in $items().
 */

// ------------------------------------------------------------
// 1) Collect every audits[] array the workflow already holds
// ------------------------------------------------------------
const audits = [];

// page 1  (Ticket Audit always returns one item)
for (const itm of $items('Ticket Audit')) {
	if (Array.isArray(itm.json.audits)) audits.push(...itm.json.audits);
}

// page 2-N  (may be zero items if the ticket fits on one page)
for (const itm of $items('Get Next Audit Page')) {
	if (Array.isArray(itm.json.audits)) audits.push(...itm.json.audits);
}

if (!audits.length) throw new Error('No audits found – make sure node names match');

// Zendesk already gives oldest➜newest, but enforce it anyway
audits.sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

// ------------------------------------------------------------
// 2) Discover requester_id from the dedicated “requester_id” event
//    (it appears only once, near the very beginning)
// ------------------------------------------------------------
let requesterId = null;

for (const audit of audits.slice(0, 5)) {          // first few audits are enough
	for (const ev of audit.events || []) {
		if ((ev.type === 'Create' || ev.type === 'Change') &&
		    ev.field_name === 'requester_id' &&
		    ev.value) {
			requesterId = Number(ev.value);        // Zendesk stores it as string
			break;
		}
	}
	if (requesterId) break;
}

// Fallback: first public comment if the special event is missing
if (!requesterId) {
	for (const audit of audits) {
		for (const ev of audit.events || []) {
			if (ev.type === 'Comment' && ev.public) {
				requesterId = ev.author_id;
				break;
			}
		}
		if (requesterId) break;
	}
}

if (!requesterId) throw new Error('Unable to determine requester_id');

// ------------------------------------------------------------
// 3) Walk backwards to locate the requester’s last public reply
// ------------------------------------------------------------
let lastComment = null;

for (let i = audits.length - 1; i >= 0 && !lastComment; i--) {
	const audit = audits[i];
	const evs   = audit.events || [];

	for (let j = evs.length - 1; j >= 0; j--) {
		const ev = evs[j];

		if (ev.type === 'Comment' &&
		    ev.public === true &&
		    ev.author_id === requesterId) {

			lastComment = {
				body       : ev.body || ev.plain_body || '',
				created_at : audit.created_at,   // audit timestamp
				audit_id   : audit.id
			};
			break;
		}
	}
}

// ------------------------------------------------------------
// 4) Output a single tidy item
// ------------------------------------------------------------
return [{
	json: {
		requester_id        : requesterId,
		last_end_user_comment: lastComment        // null if the user never replied
	}
}];

