/**********************************************************************
 *  “Audits – comments + notifications only”
 *
 *  INPUT  : items from
 *           • Ticket Audit            (page-1)
 *           • Get Next Audit Page     (page-2 … page-N)
 *
 *  OUTPUT : 1 item
 *           {
 *             "audits": [
 *                {
 *                  "id"        : 23076188830354,
 *                  "created_at": "2024-12-04T23:01:42Z",
 *                  "events"    : [
 *                     { …filtered Comment… },
 *                     { …filtered Notification… }
 *                  ]
 *                },
 *                …
 *             ]
 *           }
 *********************************************************************/

/* ------------------------------------------------------------------ */
/* 1.  Gather every audits[] array                                     */
/* ------------------------------------------------------------------ */
const allAudits = [];

// first page
for (const itm of $items('Ticket Audit')) {
	if (Array.isArray(itm.json.audits)) allAudits.push(...itm.json.audits);
}

// page 2-N
for (const itm of $items('Get Next Audit Page')) {
	if (Array.isArray(itm.json.audits)) allAudits.push(...itm.json.audits);
}

if (!allAudits.length) throw new Error('No audits found – check node names');

// guarantee chronological order
allAudits.sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

/* ------------------------------------------------------------------ */
/* 2.  Build a Zendesk-like structure with only interesting events     */
/* ------------------------------------------------------------------ */
const filteredAudits = [];

for (const audit of allAudits) {
	const wantedEvents = [];

	for (const ev of audit.events || []) {

		if (ev.type === 'Comment') {
			wantedEvents.push({
				type      : 'Comment',
				author_id : ev.author_id ?? audit.author_id,
				public    : ev.public,
				body      : ev.plain_body || ev.body || '',
				created_at: audit.created_at
			});

		} else if (ev.type === 'Notification') {
			wantedEvents.push({
				type       : 'Notification',
				recipients : ev.recipients || [],
				subject    : ev.subject || '',
				body       : ev.body || '',
				created_at : audit.created_at
			});
		}
	}

	// keep only audits that still contain at least one event
	if (wantedEvents.length) {
		filteredAudits.push({
			id         : audit.id,
			created_at : audit.created_at,
			events     : wantedEvents
		});
	}
}

/* ------------------------------------------------------------------ */
/* 3.  Emit one tidy item                                              */
/* ------------------------------------------------------------------ */
return [{
	json: {
		audits: filteredAudits          // fully parseable JSON, no stringifying
	}
}];

