/* helper: remove null values deeply */
function stripNulls(v) {
  if (v === null) return undefined;
  if (Array.isArray(v)) return v.map(stripNulls).filter(x => x !== undefined);
  if (typeof v === 'object') {
    const o = {};
    for (const [k, val] of Object.entries(v)) {
      const c = stripNulls(val);
      if (c !== undefined) o[k] = c;
    }
    return o;
  }
  return v;
}

/* helper: turn Change/tags into tags_added / tags_removed */
function compactTagChange(ev) {
  const isTags =
    ev.type === 'Change' &&
    ev.field_name === 'tags' &&
    Array.isArray(ev.value) &&
    Array.isArray(ev.previous_value);

  if (!isTags) return [ev];

  const added   = ev.value.filter(t => !ev.previous_value.includes(t));
  const removed = ev.previous_value.filter(t => !ev.value.includes(t));

  if (!added.length && !removed.length) return [];     // no real change

  const out = { type: 'Change' };
  if (added.length)   out.tags_added   = added;
  if (removed.length) out.tags_removed = removed;
  return [out];
}

/* helper: keep exactly one `body` */
function pickBody(ev) {
  const text = s => typeof s === 'string' && s.trim();
  if (!text(ev.body)) {
    ev.body = text(ev.plain_body) ? ev.plain_body
          : text(ev.html_body)   ? ev.html_body
          : ev.body;
  }
  delete ev.plain_body;
  delete ev.html_body;
  return ev;
}

/* -------- MAIN --------------------------------------------------- */
const auditsIn = items[0].json.audits ?? [];

const auditsOut = auditsIn.map(a => {
  const eventsProcessed = (a.events ?? [])
    .flatMap(compactTagChange)   // maybe drop empty tag-diffs
    .map(pickBody)               // single body
    .map(stripNulls);            // purge nulls inside events

  return {
    id         : a.id,
    created_at : a.created_at,
    events     : eventsProcessed,
  };
});

// emit ONE item with audits array
return [{ json: { audits: auditsOut } }];

