	const cleanedAudits = audits
		.map(audit => {
			const keptEvents = (audit.events || []).filter(ev =>
				ev.type === 'Comment' || ev.type === 'Notification',
			);
			return { ...audit, events: keptEvents };
		})
		/* 3. drop audits that are now event-less */
		.filter(audit => audit.events.length > 0);

	/* 4. write the cleaned audits back into the item */
