allAudits.sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

/* ------------------------------------------------------------------ */
/* 2.  Build a Zendesk-like structure with only interesting events     */
/* ------------------------------------------------------------------ */
const filteredAudits = [];

for (const audit of allAudits) {
	const wantedEvents = [];

	for (const ev of audit.events || []) {

		if (ev.type === 'Comment') {
			wantedEvents.push({
				type      : 'Comment',
				author_id : ev.author_id ?? audit.author_id,
				public    : ev.public,
				body      : ev.plain_body || ev.body || '',
				created_at: audit.created_at
			});

		} else if (ev.type === 'Notification') {
			wantedEvents.push({
				type       : 'Notification',
				recipients : ev.recipients || [],
				subject    : ev.subject || '',
				body       : ev.body || '',
				created_at : audit.created_at
			});
		}
	}

	// keep only audits that still contain at least one event
	if (wantedEvents.length) {
		filteredAudits.push({
			id         : audit.id,
			created_at : audit.created_at,
			events     : wantedEvents
		});
	}
}

/* ------------------------------------------------------------------ */
/* 3.  Emit one tidy item                                              */
/* ------------------------------------------------------------------ */
return [{
	json: {
		audits: filteredAudits          // fully parseable JSON, no stringifying
	}
}];

// Run Once for All Items

const input = items[0].json;

if (!input?.audits || !Array.isArray(input.audits)) {
  return [{ json: { events: [] } }];
}

// 1. Flatten all events, preserving audit context if needed
const allEvents = input.audits.flatMap(audit => {
  if (!Array.isArray(audit.events)) return [];
  return audit.events.map(event => ({
    ...event,
    audit_id: audit.id,
    audit_created_at: audit.created_at,
  }));
});

// 2. Sort by event.created_at descending (most recent first)
allEvents.sort((a, b) => {
  return new Date(b.created_at) - new Date(a.created_at);
});

// 3. Take the most recent 10
const latest10 = allEvents.slice(0, 10);

return [
  {
    json: {
      events: latest10
    }
  }
];
